    "text": "Compare the surds \\(4\\sqrt{3}\\) and \\(3\\sqrt{5}\\).",
    "options": [
      {
        "text": "\\(4\\sqrt{3} < 3\\sqrt{5}\\)",
        "isCorrect": false
      },
      {
        "text": "\\(4\\sqrt{3} = 3\\sqrt{5}\\)",
        "isCorrect": false
      },
      {
        "text": "Cannot be compared",
        "isCorrect": false
      },
      {
        "text": "\\(4\\sqrt{3} > 3\\sqrt{5}\\)",
        "isCorrect": true
      }
    ],
    "correctAnswer": "D",
    "solution": "Step 1: Convert to pure surds: \\(4\\sqrt{3} = \\sqrt{4^2 \\times 3} = \\sqrt{16 \\times 3} = \\sqrt{48}\\).\nStep 2: \\(3\\sqrt{5} = \\sqrt{3^2 \\times 5} = \\sqrt{9 \\times 5} = \\sqrt{45}\\).\nStep 3: Since \\(48 > 45\\), \\(\\sqrt{48} > \\sqrt{45} \\implies 4\\sqrt{3} > 3\\sqrt{5}\\).",
