    "questionCode": "MH-9-MTH1-2-2.5.2-OSC-101",
    "text": "What is the conjugate pair of the binomial surd \\((\\sqrt{3} + \\sqrt{4})\\)?",
    "options": [
      {
        "text": "\\((-\\sqrt{3} - \\sqrt{4})\\)",
        "isCorrect": false
      },
      {
        "text": "\\((\\sqrt{3} + \\sqrt{4})\\)",
        "isCorrect": false
      },
      {
        "text": "\\((3 - 4)\\)",
        "isCorrect": false
      },
      {
        "text": "\\((\\sqrt{3} - \\sqrt{4})\\)",
        "isCorrect": true
      }
    ],
    "correctAnswer": "D",
    "solution": "Step 1: The conjugate pair of \\((\\sqrt{a} + \\sqrt{b})\\) is \\((\\sqrt{a} - \\sqrt{b})\\).\nStep 2: Their product \\((\\sqrt{3} + \\sqrt{4})(\\sqrt{3} - \\sqrt{4}) = 3 - 4\\) is always a rational number.\nStep 3: Hence, the conjugate is \\((\\sqrt{3} - \\sqrt{4})\\).",
