    "solution": "Step 1: If \\(|x - a| = b\\) where \\(b > 0\\), then \\(x - a = b\\) or \\(x - a = -b\\).\nStep 2: Case 1: \\(x - 3 = 4 \\implies x = 7\\).\nStep 3: Case 2: \\(x - 3 = -4 \\implies x = -1\\). Solutions are \\(x = 7\\) or \\(x = -1\\).",
